import 'transport_location_update.dart';
class LocationUpdateQueueEntry { const LocationUpdateQueueEntry({required this.update, required this.state}); final TransportLocationUpdate update; final LocationUpdateQueueState state; }
class LocationUpdateQueue { final Map<String, LocationUpdateQueueEntry> _entries = {}; Future<void> enqueue(TransportLocationUpdate update) async { _entries.putIfAbsent(update.clientLocationId, () => LocationUpdateQueueEntry(update: update, state: LocationUpdateQueueState.pending)); } Future<List<LocationUpdateQueueEntry>> pending() async => _entries.values.where((entry) => entry.state == LocationUpdateQueueState.pending).toList(growable: false); Future<void> markSynced(String clientLocationId) async { final entry = _entries[clientLocationId]; if (entry != null) _entries[clientLocationId] = LocationUpdateQueueEntry(update: entry.update, state: LocationUpdateQueueState.synced); } }
